#!/bin/sh
#
# Generate datasets.nsh from ../datasets.tsv.
#
#   ./gen-datasets-nsh.sh > datasets.nsh
#
# Geant4.nsi includes the result and inserts the three macros it defines, so
# the Windows installer's component list comes from the same table as the
# macOS and Debian ones.  After a Geant4 upgrade: regenerate datasets.tsv with
# ../update-datasets.sh, then regenerate this.
#
# The generated file is committed, so that building the installer on Windows
# needs nothing but makensis.

set -eu

here=$(cd "$(dirname "$0")" && pwd)
table=${1:-$here/../datasets.tsv}

[ -r "$table" ] || { echo "gen-datasets-nsh.sh: no $table" >&2; exit 1; }

printf ';\n'
printf '; Geant4 dataset sections, GENERATED by gen-datasets-nsh.sh from\n'
printf '; datasets.tsv.  Do not edit; edit the table and regenerate.\n'
printf ';\n\n'

# --- the sections -----------------------------------------------------------
printf '!macro G4_DATA_SECTIONS\n'
awk -F'\t' '
    /^#/ || NF < 5 { next }
    {
        dir = $1; var = $2; archive = $3
        # The archive name the macro wants is without the .tar.gz.
        sub(/\.tar\.gz$/, "", archive)
        # Every dataset is selected by default; the user unticks what they do
        # not need, and the description says which ones Geant4 cannot run without.
        printf "\n  Section \"%s\" SEC_%s\n", dir, var
        printf "    !insertmacro DownloadData \"%s\" \"%s\" \"%s\"\n", archive, dir, var
        printf "  SectionEnd\n"
    }
' "$table"
printf '!macroend\n\n'

# --- the component descriptions ---------------------------------------------
printf '!macro G4_DATA_DESCRIPTIONS\n'
awk -F'\t' '
    /^#/ || NF < 5 { next }
    {
        dir = $1; var = $2; required = $5
        desc = $6
        gsub(/"/, "$\\\"", desc)
        tail = (required == 1) ? " (required: Geant4 cannot run without it)" : ""
        printf "  !insertmacro MUI_DESCRIPTION_TEXT ${SEC_%s} \"%s: %s%s\"\n", \
               var, dir, desc, tail
    }
' "$table"
printf '!macroend\n\n'

# --- the uninstaller --------------------------------------------------------
printf '!macro G4_DATA_UNSETVARS\n'
awk -F'\t' '
    /^#/ || NF < 5 { next }
    { printf "  !insertmacro un.DeleteVar \"%s\"\n", $2 }
' "$table"
printf '  !insertmacro un.DeleteVar "GEANT4_DATA_DIR"\n'
printf '!macroend\n'
